// ZOD-FND-009: emits packages/shared_ui/lib/src/icons/zodiann_icons.g.dart
// from parsed icons. Deterministic: icons sorted by name (code units),
// doubles printed with double.toString(), formatted by the pinned SDK's
// `dart format`.
import 'dart:convert';
import 'dart:io';

import 'svg_icon.dart';

/// The generated file's path, relative to the workspace root. `dart format`
/// uses it to find the formatter settings that `format:check` applies.
const generatedPath = 'packages/shared_ui/lib/src/icons/zodiann_icons.g.dart';

const _header =
    '// GENERATED by tool/gen_icons.dart from '
    'design-reference/zodiann/assets/icons/*.svg (ZOD-FND-009).\n'
    '// Do not edit. Regenerate: fvm dart run tool/gen_icons.dart\n';

/// The unformatted library for [icons].
String emitIconsLibrary(List<SvgIcon> icons) {
  final sorted = [...icons]..sort((a, b) => a.name.compareTo(b.name));
  final out = StringBuffer(_header)
    ..writeln()
    ..writeln("import 'dart:ui' show StrokeCap, StrokeJoin;")
    ..writeln()
    ..writeln("import 'zodiann_icon_data.dart';")
    ..writeln()
    ..writeln('/// The Zodiann icon set (MASTER §11): 24-unit grid, 1.6 round')
    ..writeln('/// stroke. Draw one with `ZodiannIcon(ZodiannIcons.x)`.')
    ..writeln('abstract final class ZodiannIcons {');
  for (final icon in sorted) {
    out
      ..writeln('  /// `${icon.name}.svg`.')
      ..writeln(
        '  static const ZodiannIconData ${icon.name} = ZodiannIconData('
        "name: '${icon.name}', "
        'viewBoxWidth: ${_n(icon.viewBoxWidth)}, '
        'viewBoxHeight: ${_n(icon.viewBoxHeight)}, '
        'shapes: [${icon.shapes.map(_shape).join(', ')}],);',
      );
  }
  out
    ..writeln()
    ..writeln('  /// Every icon, in name order.')
    ..writeln(
      '  static const List<ZodiannIconData> values = '
      '[${sorted.map((i) => i.name).join(', ')}];',
    )
    ..writeln('}');
  return out.toString();
}

String _n(double v) => v.toString();

String _shape(SvgShape shape) => switch (shape) {
  SvgPath(:final commands, :final paint) =>
    'ZodiannIconPath([${commands.map(_command).join(', ')}], ${_paint(paint)})',
  SvgCircle(:final cx, :final cy, :final r, :final paint) =>
    'ZodiannIconCircle(${_n(cx)}, ${_n(cy)}, ${_n(r)}, ${_paint(paint)})',
  SvgRect(
    :final x,
    :final y,
    :final width,
    :final height,
    :final rx,
    :final ry,
    :final paint,
  ) =>
    'ZodiannIconRect(${_n(x)}, ${_n(y)}, ${_n(width)}, ${_n(height)}, '
        '${_n(rx)}, ${_n(ry)}, ${_paint(paint)})',
};

String _command(SvgCommand c) => switch (c) {
  MoveTo(:final x, :final y) => 'IconMoveTo(${_n(x)}, ${_n(y)})',
  LineTo(:final x, :final y) => 'IconLineTo(${_n(x)}, ${_n(y)})',
  CubicTo(:final x1, :final y1, :final x2, :final y2, :final x, :final y) =>
    'IconCubicTo(${_n(x1)}, ${_n(y1)}, ${_n(x2)}, ${_n(y2)}, '
        '${_n(x)}, ${_n(y)})',
  ArcTo(
    :final x,
    :final y,
    :final rx,
    :final ry,
    :final rotation,
    :final largeArc,
    :final sweep,
  ) =>
    'IconArcTo(${_n(x)}, ${_n(y)}, ${_n(rx)}, ${_n(ry)}, ${_n(rotation)}, '
        '$largeArc, $sweep)',
  Close() => 'IconClose()',
};

String _paint(SvgPaint paint) {
  final stroke = paint.stroke;
  final arguments = [
    if (paint.fill) 'fill: true',
    if (stroke != null)
      'stroke: ZodiannIconStroke(${_n(stroke.width)}, '
          'StrokeCap.${stroke.cap}, StrokeJoin.${stroke.join})',
  ];
  return 'ZodiannIconPaint(${arguments.join(', ')})';
}

/// [source] formatted by the running SDK's `dart format`.
Future<String> formatDart(String source) async {
  final process = await Process.start(Platform.resolvedExecutable, [
    'format',
    '--stdin-name=$generatedPath',
  ]);
  process.stdin
    ..encoding = utf8
    ..write(source);
  await process.stdin.close();
  final output = process.stdout.transform(utf8.decoder).join();
  final errors = process.stderr.transform(utf8.decoder).join();
  final code = await process.exitCode;
  if (code != 0) {
    throw IconGeneratorException('dart format failed ($code): ${await errors}');
  }
  return (await output).replaceAll('\r\n', '\n');
}
